        ?sensorMin geo:hasGeometry ?geomMin .
        ?geomMin geo:asWKT ?wktMin .
        ?minElevQv qudt:numericValue ?minElev .
      }
      ORDER BY ASC(?minElev)
      LIMIT 1
    }
